    diagram: [zel(0.1, 0.2, 0.9, 0.8), pel("goal", 0.9, 0.5), pel("keeper", 0.86, 0.5), pel("playerC", 0.2, 0.3), pel("playerA", 0.4, 0.28), pel("playerB", 0.55, 0.55), pel("ball", 0.23, 0.32), ael("arrowPass", 0.23, 0.32, 0.38, 0.28), ael("arrowDribble", 0.42, 0.3, 0.8, 0.45)],
